package v1alpha1

import (
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// AccessAssumption describes a request to assume access to a cloud account
// +k8s:openapi-gen=false
type AccessAssumption struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`
	Spec              AccessAssumptionSpec `json:"spec,omitempty"`
}

func (AccessAssumption) APIPath() string {
	return ""
}

// AccessAssumptionSpec describes the account and role that the assumption is targeting
// +k8s:openapi-gen=false
type AccessAssumptionSpec struct {
	// CloudAccount specifies which cloud account this access request is for
	CloudAccount *CloudAccountReference `json:"cloudAccount,omitempty"`
	// Role identifies which role to assume (must be present in UserRoles for the referenced
	// CloudAccount)
	Role string `json:"role,omitempty"`
	// Portal indicates that this request is for portal rather than API/CLI access
	Portal bool `json:"portal,omitempty"`
}

// AccessAssumptionResult is the returned details of performing an assumption, including the temporary
// credentials for the session created for the user
// +k8s:openapi-gen=false
type AccessAssumptionResult struct {
	// Credentials will be populated with the appropriate key-value pairs to access the cloud
	// provider in question. The keys of this will vary with the cloud provider.
	Credentials map[string]string `json:"credentials,omitempty"`
	// Expires is the time the requested access expires
	Expires metav1.Time `json:"expires,omitempty"`
}

// AccessAssumptionPermissions describes what roles the current user can access
// +k8s:openapi-gen=false
type AccessAssumptionPermissions struct {
	// Account specifies which cloud account this permission reference is for
	Account CloudAccountReference
	// User specifies which user this permission reference is for
	User string
	// AccountType details the type of cloud account we're talking about, provided for convenience
	AccountType string `json:"accountType"`
	// Cloud details which cloud this cloud account is for, provided for convenience
	Cloud string `json:"cloud"`
	// UserRoles describes the available user roles on this cloud account
	UserRoles map[string]AccessAssumptionPermission `json:"userRoles,omitempty"`
}

// AccessAssumptionPermission desribes whether the current user can access a specific user role
type AccessAssumptionPermission struct {
	// UserRole identifies which role this permission is for
	UserRole string `json:"userRole"`
	// Status indicates the current status of this user role
	Status CloudAccountUserRoleStatus `json:"status"`
	// Allowed will indicate if the user is currently allowed to assume this role
	Allowed bool `json:"allowed"`
	// DenyReasons lists zero or more reasons why the user may not be able to currently assume this
	// role. May not always be populated.
	DenyReasons []DenyReason `json:"denyReasons"`
}

// DenyReason describes why an access assumption is not permitted
type DenyReason string

// DenyReasonNoPolicy indicates that no policy is applicable for this role for the current user
const DenyReasonNoPolicy DenyReason = "NoPolicy"

// DenyReasonTimeConstraint indicates that the access would be permitted during certain time periods
// but is not permitted at the current time
const DenyReasonTimeConstraint DenyReason = "TimeConstraint"

// DenyReasonNetworkConstraint indicates that the access would be permitted for the user when
// accessing from certain network locations, but their current network location is not permitted
const DenyReasonNetworkConstraint DenyReason = "NetworkConstraint"
